package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.estimation.QuadProbe;
import org.eclipse.rdf4j.sail.lmdb.estimation.QuadValueHash;
import org.eclipse.rdf4j.sail.lmdb.sketch.SketchBasedJoinEstimator;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class LmdbDisabledSketchCommitPersistenceTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:disabled-sketch-fence:p");

	@Test
	void disabledSketchCommitCannotLeaveOldV8SnapshotCurrent(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path directory = evidence.resolve("store");
		seedSnapshot(directory);
		Path snapshot = directory.resolve("join-estimator.rjes/synopsis-v8.bin");
		Path backup = evidence.resolve("original-v8-backup.bin");
		Files.copy(snapshot, backup);
		LmdbStore disabled = new LmdbStore(directory.toFile(), config(false));
		SailRepository disabledRepository = new SailRepository(disabled);
		disabledRepository.init();
		boolean markerAfterCommit;
		try {
			LmdbTestUtil.awaitPostReadyInitialization(disabled, 30, TimeUnit.SECONDS);
			try (var connection = disabledRepository.getConnection()) {
				connection.add(VF.createIRI("urn:disabled-sketch-fence:second"), PREDICATE, VF.createLiteral(2));
			}
			markerAfterCommit = Files.exists(directory.resolve("join-estimator.rjes/synopsis-v8.rebuild"));
			assertEquals(-1L, Files.mismatch(snapshot, backup), "disabled sketches must preserve the original v8 file");
		} finally {
			disabledRepository.shutDown();
		}

		LmdbStore reopened = new LmdbStore(directory.toFile(), config(true));
		SailRepository enabledRepository = new SailRepository(reopened);
		enabledRepository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(reopened, 30, TimeUnit.SECONDS);
			assertTrue(reopened.awaitSketchesReady(30, TimeUnit.SECONDS));
			long rows;
			try (var connection = enabledRepository.getConnection()) {
				rows = connection.size();
			}
			SketchBasedJoinEstimator estimator = reopened.getBackingStore().getSketchBasedJoinEstimator();
			QuadProbe probe = new QuadProbe(QuadProbe.PREDICATE, QuadProbe.OBJECT, 0L,
					QuadValueHash.hash(PREDICATE), 0L, 0L, estimator.quadSnapshotIdentity());
			var estimate = estimator.synopsisService().probe(probe);
			assertAll("disabled-mode commits cannot certify the old snapshot",
					() -> assertTrue(markerAfterCommit,
							"the old v8 file must be fenced before disabled commit returns"),
					() -> assertEquals(2L, rows),
					() -> assertTrue(estimate.usable()),
					() -> assertEquals(2.0d, estimate.rows().estimate()));
		} finally {
			enabledRepository.shutDown();
		}
	}

	@Test
	void freshDisabledStoreDoesNotCreateSketchSidecars(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbStore disabled = new LmdbStore(directory.toFile(), config(false));
		SailRepository repository = new SailRepository(disabled);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(disabled, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:disabled-sketch-fence:fresh"), PREDICATE, VF.createLiteral(1));
			}
		} finally {
			repository.shutDown();
		}
		assertFalse(Files.exists(directory.resolve("join-estimator.rjes")),
				"a store with sketches disabled and no old snapshot must not gain sketch sidecars");
	}

	private static void seedSnapshot(Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config(true));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:disabled-sketch-fence:first"), PREDICATE, VF.createLiteral(1));
			}
			assertTrue(store.forceFlushSketchEstimator());
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			estimator.persistIfDirty();
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config(boolean enabled) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(enabled)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L)
				.setBackgroundRawSamplingEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false);
		config.setExperimentalQueryOptimizations(enabled);
		return config;
	}
}
